package com.silverroom.camera;
import android.graphics.*;
import java.util.*;

/** One decoded source at a time; identical geometry for the small preview and saved page. */
final class PrintRenderer {
    interface Source {Bitmap image(String id,int edge)throws Exception;PrintMetadata metadata(String id);}
    interface Cancel {boolean cancelled();}
    static Bitmap render(Source source,List<String> ids,PrintOptions options,int page,int edge,Cancel cancel)throws Exception{int first=options.first(page),count=options.count(page,ids.size());if(count==0)throw new java.io.IOException("没有可导出的照片");if(!options.contact){String id=ids.get(first);Bitmap input=source.image(id,edge);try{String[] captions=source.metadata(id).captions(options);PrintLayout layout=PrintLayout.single(input.getWidth(),input.getHeight(),options.style,captions.length,edge);Bitmap output=Bitmap.createBitmap(layout.width,layout.height,Bitmap.Config.ARGB_8888);try{Canvas canvas=new Canvas(output);canvas.drawColor(0xfffffaf2);draw(canvas,input,layout,captions);if(cancel.cancelled())throw new java.io.InterruptedIOException("已取消导出");return output;}catch(Exception|OutOfMemoryError e){output.recycle();throw e;}}finally{input.recycle();}}
        int[] size=PrintLayout.sheetSize(edge);Bitmap output=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);try{Canvas canvas=new Canvas(output);canvas.drawColor(0xfffffaf2);for(int i=0;i<count;i++){if(cancel.cancelled())throw new java.io.InterruptedIOException("已取消导出");String id=ids.get(first+i);float[] cell=PrintLayout.cell(i,size[0],size[1]);Bitmap input=source.image(id,Math.max(1,Math.round(Math.max(cell[2],cell[3]))));try{String[] captions=source.metadata(id).captions(options);PrintLayout layout=PrintLayout.contact(input.getWidth(),input.getHeight(),options.style,captions.length,Math.round(Math.max(cell[2],cell[3])));float[] fit=PrintLayout.fit(layout.width,layout.height,cell[0],cell[1],cell[2],cell[3]);canvas.save();canvas.translate(fit[0],fit[1]);canvas.scale(fit[2]/layout.width,fit[3]/layout.height);draw(canvas,input,layout,captions);canvas.restore();}finally{input.recycle();}}return output;}catch(Exception|OutOfMemoryError e){output.recycle();throw e;}}
    private static void draw(Canvas canvas,Bitmap image,PrintLayout layout,String[] captions){Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);paint.setColor(0xfffffaf2);canvas.drawRect(0,0,layout.width,layout.height,paint);canvas.drawBitmap(image,null,new RectF(layout.left,layout.top,layout.left+layout.photoWidth,layout.top+layout.photoHeight),paint);paint.setColor(0xff28554f);paint.setTypeface(Typeface.create("sans-serif",0));paint.setTextSize(layout.font);for(int i=0;i<captions.length;i++){String text=captions[i];int end=text.length();while(end>0&&paint.measureText(text.substring(0,end)+(end<text.length()?"…":""))>layout.photoWidth)end--;canvas.drawText(text.substring(0,end)+(end<text.length()?"…":""),layout.textX,layout.textY+i*layout.lineHeight,paint);}}
}
